INSERT INTO `termandcondition` (`id`, `Code`, `Title`, `Description`) VALUES ('1920034', 'Onboarding_OFAC_TnC', 'Personal Info OFAC', 'OFAC disclaimer for Personal Info page');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450042', '1920034', 'en-US', '1.0', 'OFAC disclaimer for Personal Info page', 'To Help the government fight the funding of terrorism and money laundering activites, Federal law requires all financial institutions to obtain, verify and record information that identifies each person who opens an account. In the same instances, we may use outside sources to confirm the information provided by you. The information you provide is protected by our privacy policy and Federal Law.What this means for you: by clicking continue, you authorize us to collect your name, address, date of birth, ID and other information that will allow us to identify you.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditionapp` (`id`, `TermAndConditionId`, `AppId`, `createdby`) VALUES ('2312364', '1920034', 'ONBOARDING', 'Kony user');
INSERT INTO `termandcondition` (`id`, `Code`, `Title`, `Description`) VALUES ('1920027', 'Onboarding_eSign_Agreement', 'Existing Member e-Sign Agreement', 'eSign agreement at Existing Member check page');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450027', '1920027', 'en-US', '1.0', 'eSign agreement at Existing Member check page', 'https://apply.usbank.com/api/documents/disclosures/ESIGN_Consent_Agreement_Auth.pdf', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditionapp` (`id`, `TermAndConditionId`, `AppId`, `createdby`) VALUES ('2312357', '1920027', 'ONBOARDING', 'Kony user');
INSERT INTO `termandcondition` (`id`, `Code`, `Title`, `Description`) VALUES ('1920028', 'Onboarding_GoogleMaps_Disclosure', 'Address & ID  Google Maps disclosure', 'Google Maps disclosure at Address and ID page');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450028', '1920028', 'en-US', '1.0', 'Google Maps disclosure at Address and ID page', 'By providing your address in this application, you agree to and are bound by Google’s Terms of Service and the Google Privacy Policy. Additionally, you are bound by our privacy policy and any and all data retention requirements imposed by law.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450034', '1920028', 'es-ES', '1.0', 'Google Maps disclosure at Address and ID page', 'Al proporcionar su dirección en esta aplicación, acepta y se compromete a cumplir los términos del servicio de Google y la Política de privacidad de Google. Además, usted está obligado por nuestra política de privacidad y cualquier y todos los requisitos de retención de datos impuestas por la ley.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450035', '1920028', 'fr-FR', '1.0', 'Google Maps disclosure at Address and ID page', 'En fournissant votre adresse dans cette application, vous acceptez et êtes lié par les conditions d’utilisation de Google et la politique de confidentialité de Google. De plus, vous êtes lié par notre politique de confidentialité et toutes les exigences de conservation des données imposées par la loi.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditionapp` (`id`, `TermAndConditionId`, `AppId`, `createdby`) VALUES ('2312358', '1920028', 'ONBOARDING', 'Kony user');
INSERT INTO `termandcondition` (`id`, `Code`, `Title`, `Description`) VALUES ('1920029', 'Onboarding_Funding_OTP_Disclaimer', 'Funding - Payment Type/OTP disclaimer', 'Funding dislaimer - Payment Type & Funding OTP pages');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450029', '1920029', 'en-US', '1.0', 'Funding dislaimer - Payment Type & Funding OTP pages', 'You can choose to fund your account either using same bank account or an account from a different bank. You will have to provide authenticated account information once your account is created in our record, thus we will use to fund your account.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450036', '1920029', 'es-ES', '1.0', 'Funding dislaimer - Payment Type & Funding OTP pages', 'Puede optar por transferir fondos para su cuenta utilizando una cuenta con Banco Infinity o una cuenta de un banco distinto. Tendrá que autenticarse una vez que cree su cuenta en nuestro registro, por lo que usaremos para transferir fondos para su cuenta(s).', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450037', '1920029', 'fr-FR', '1.0', 'Funding dislaimer - Payment Type & Funding OTP pages', 'Vous pouvez choisir de financer votre compte en utilisant le même compte bancaire ou un compte d’une autre banque. Vous devrez fournir des informations de compte authentifiées une fois que votre compte est créé dans notre dossier, donc nous utiliserons pour financer votre compte.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditionapp` (`id`, `TermAndConditionId`, `AppId`, `createdby`) VALUES ('2312359', '1920029', 'ONBOARDING', 'Kony user');
INSERT INTO `termandcondition` (`id`, `Code`, `Title`, `Description`) VALUES ('1920030', 'Onboarding_Funding_Disclaimer', 'Funding - Existing Accounts/Manual Accounts disclaimer', 'Funding dislaimer - Existing & Manual Account Details pages');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450030', '1920030', 'en-US', '1.0', 'Funding dislaimer - Existing & Manual Account Details pages', '• Not all accounts are eligible for funds transfer.\n• Funds transfer completed through Infinity online banking before the cut-off time on a business day will be posted to your eligible account the same day. Credit card, line of credit loan and mortgage transactions may take up to 3 business days to process, but will be posted on the business date when the transaction was made.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450038', '1920030', 'es-ES', '1.0', 'Funding dislaimer - Existing & Manual Account Details pages', '• No todas las cuentas son elegibles para la transferencia de fondos.\n• La transferencia de fondos completada a través de la banca en línea de Infinity antes de la hora límite en un día hábil se registrará en su cuenta elegible el mismo día. Las transacciones de tarjetas de crédito, préstamos de línea de crédito e hipotecas pueden tardar hasta 3 días hábiles en procesarse, pero se registrarán en la fecha de la empresa cuando se realizó la transacción.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450039', '1920030', 'fr-FR', '1.0', 'Funding dislaimer - Existing & Manual Account Details pages', '• Tous les comptes ne sont pas admissibles au transfert de fonds.\n• Transfert de fonds effectué par le biais des services bancaires en ligne Infinity avant que l’heure limite d’un jour ouvrable ne soit affichée sur votre compte admissible le même jour. Le traitement des transactions par carte de crédit, de marge de crédit et d’hypothèque peut prendre jusqu’à 3 jours ouvrables, mais il sera affiché à la date de l’opération.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditionapp` (`id`, `TermAndConditionId`, `AppId`, `createdby`) VALUES ('2312360', '1920030', 'ONBOARDING', 'Kony user');
INSERT INTO `termandcondition` (`id`, `Code`, `Title`, `Description`) VALUES ('1920031', 'Onboarding_Funding_Acknowledgement_Disclaimer', 'Funding - Acknowledgement disclaimer', 'Funding dislaimer - Acknowledgement page');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450031', '1920031', 'en-US', '1.0', 'Funding dislaimer - Acknowledgement page', 'Auto approval of the application does not guarantee the creation of an account. When account gets created, we will send an acknowledgement mail to you.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450040', '1920031', 'es-ES', '1.0', 'Funding dislaimer - Acknowledgement page', 'La aprobación automática de la aplicación no garantiza la creación de la cuenta. Cuando se cree la cuenta, le enviaremos un correo de confirmación', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450041', '1920031', 'fr-FR', '1.0', 'Funding dislaimer - Acknowledgement page', 'L’approbation automatique de la demande ne garantit pas la création d’un compte. Lorsque le compte est créé, nous vous envoyons un courrier de remerciement', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditionapp` (`id`, `TermAndConditionId`, `AppId`, `createdby`) VALUES ('2312361', '1920031', 'ONBOARDING', 'Kony user');
INSERT INTO `termandcondition` (`id`, `Code`, `Title`, `Description`) VALUES ('1920032', 'Onboarding_IDScan_Disclaimer', 'ID Scan disclaimer', 'ID Scan disclaimer');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450032', '1920032', 'en-US', '1.0', 'ID Scan disclaimer', 'The scan your ID document retrieves information used only on the context of this application. The bank stores the scanned document as a proof of identity and in accordance to local regulations.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditionapp` (`id`, `TermAndConditionId`, `AppId`, `createdby`) VALUES ('2312362', '1920032', 'ONBOARDING', 'Kony user');
INSERT INTO `termandcondition` (`id`, `Code`, `Title`, `Description`) VALUES ('1920033', 'Onboarding_ProductDashboard_Disclaimer', 'Product Dashboard disclaimer', 'Product Dasboard disclaimer');
INSERT INTO `termandconditiontext` (`id`, `TermAndConditionId`, `LanguageCode`, `Version_Id`, `Description`, `Content`, `ContentType_id`, `ContentModifiedBy`, `Status_id`) VALUES ('3450033', '1920033', 'en-US', '1.0', 'Product Dasboard disclaimer', 'Investing involves risks, and there is always the potential of losing money when you invest in securities. You should review any planned financial transactions that may have tax or legal implications with your personal tax or legal advisor.', 'TEXT', 'Kony User', 'SID_TANDC_ACTIVE');
INSERT INTO `termandconditionapp` (`id`, `TermAndConditionId`, `AppId`, `createdby`) VALUES ('2312363', '1920033', 'ONBOARDING', 'Kony user');
